head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF08200";
// 원본 : /lstproc/ULDSTF08200.gfm (손실제한 ETN 신규상장 마감처리 / 마감처리내역, 1270×750 메인 화면)
/*
 * 화면 동작
 *  - [ETN마감처리] 탭: 마감일(당일 고정)의 다음 영업일(상장일) 신규상장 종목과 상환주기를 보여 주고,
 *    담당자 확인 → 팀장승인(마감처리) 순서로 마감한다. 시스템관리자(ZSYS)는 재마감처리(이전 마감기록 삭제)를 할 수 있다.
 *  - [ETN마감처리내역] 탭: 고른 마감일의 신규상장·상환주기 마감처리(송신)내역을 조회한다.
 *  - 통신·데이터 정의는 ULDSTF08200_API.md 명세 기준(close-procs-newlisting 9종). 같은 명세의 close-procs-invst-warn 12종은
 *    이 화면 원본에 대응 기능이 없어 쓰지 않는다(결과서 §5·§10 #1).
 * 업무 분석 : conversion/conversion-front/ui/ULDSTF08200/ULDSTF08200.md (§번호는 이 문서의 절)
 */

// 화면 상태값
scwin.todayDd = "";         // 서버 현재일 (yyyyMMdd) — 원본 cGetToday("yyyymmdd")(클라이언트 날짜)
scwin.jobTitl = "";         // 직책 (03: 담당자, 그 외: 팀장) — 원본 js_jobtitl
scwin.depCd = "";           // 부서코드 (ZSYS: 시스템관리자 → 재마감처리 버튼 보임) — 원본 js_dep_cd
scwin.procJob = "";         // 진행 중인 처리명 (완료·실패 메시지 인자) — 원본 procJob

// 고정값
scwin.TAB_PROC = 0;         // [ETN마감처리] 탭 (원본 MaxTab_01 ActiveIndex 1)
scwin.TAB_SEARCH = 1;       // [ETN마감처리내역] 탭 (원본 ActiveIndex 2)
scwin.JOBTITL_CHRG = "03";  // 직책코드 — 담당자
scwin.DEP_CD_SYS = "ZSYS";  // 부서코드 — 시스템관리자

// 이 화면의 역할→버튼 매핑 — 담당자 확인·팀장승인 활성은 마감정보로 정한다(§6.6). 재마감처리는 보임/숨김으로 따로 다룬다(§6.7).
scwin.BTN_MAP = {
    revw : "btn_Revw",      // [담당자 확인]
    cls : "btn_Cls"         // [팀장승인]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 세션 정보 → init 바인딩 → 버튼 초기 상태 → [ETN마감처리] 탭 상태(마감일 = 오늘) → 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 세션·서버 날짜 — 원본 js_jobtitl·js_dep_cd 전역, cGetToday("yyyymmdd")
    scwin.jobTitl = $c.session.getUserInfo("jobtitl") ?? "";
    scwin.depCd = $c.session.getUserInfo("depCd") ?? "";
    scwin.todayDd = $c.date.getServerDateTime("yyyyMMdd");

    // 2) init 바인딩 (전환 규칙 22·37) — 마감일 단일 달력, 조회 영역 Enter 키
    $c.date.checkCalendarFormat(edt_TASK_DD, "yyyyMMdd");
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 버튼 초기 상태 — 재마감처리는 시스템관리자만 보이고, 담당자 확인·팀장승인은 마감정보 조회 뒤 정한다(그 전까지 잠금)
    scwin.applyReclsButton();
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 4) [ETN마감처리] 탭 상태 — 마감일 = 오늘, 읽기전용 (원본 setObjectValue(edt_TASK_DD, 오늘) + OnSelChanged(1) 처리 — §8 #6)
    scwin.applyTabMode(scwin.TAB_PROC);

    // 5) 조회 (원본 fn_list_sync)
    await scwin.listSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.MaxTab_01_onchange
 * @author Inswave
 * @date 2026. 10. 28
 * @description 탭 변경 — 탭에 맞춰 마감일 입력 상태를 바꾸고 다시 조회한다. (원본 MaxTab_01 OnSelChanged — §4, §6.1)
 * @param {String} tabId 선택한 탭 id
 * @param {Number} index 선택한 탭 순번
 * @returns
 * @hidden N
 */
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        scwin.applyTabMode(Number(MaxTab_01.getSelectedTabIndex()));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.MaxTab_01_onchange" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 버튼 클릭(조회 영역 Enter 키 포함) — 선택한 탭 기준으로 다시 조회한다. (원본 btn_Search onclick → fn_list_sync — §5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_New_Proc_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리] 신규상장 행 클릭 — 그 행 업무처리번호의 상환주기를 조회한다. (원본 grd_New_Proc OnClick → fn_SearchRedmpt — §5.4)
 * @param {Number} row 행 번호(화면)
 * @param {Number} col 열 번호
 * @param {String} colId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_New_Proc_oncellclick = async function (row, col, colId) {
    try {
        if (row < 0) return;    // 원본 if(row == 0) return — 머리글 클릭
        await scwin.searchRedemption(dlt_list.getCellData(row, "bzProcsNo"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.grd_New_Proc_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.grd_New_Search_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리내역] 신규상장 행 클릭 — 그 종목의 상환주기 마감처리내역을 조회한다. (원본 grd_New_Search OnClick → fn_SearchRedmptRv — §5.6)
 * @param {Number} row 행 번호(화면)
 * @param {Number} col 열 번호
 * @param {String} colId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_New_Search_oncellclick = async function (row, col, colId) {
    try {
        if (row < 0) return;    // 원본 if(row == 0) return — 머리글 클릭
        await scwin.searchRedemptionHist(dlt_newlistingHist.getCellData(row, "isuCd"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.grd_New_Search_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Recls_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 재마감처리 버튼 클릭 (시스템관리자만 보임) — 처리는 scwin.recls. (§6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Recls_onclick = async function (e) {
    try {
        await scwin.recls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.btn_Recls_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Revw_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 담당자 확인 버튼 클릭 — 처리는 scwin.revw. (§6.4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Revw_onclick = async function (e) {
    try {
        await scwin.revw();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.btn_Revw_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Cls_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 팀장승인 버튼 클릭 — 처리는 scwin.cls. (§6.5)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Cls_onclick = async function (e) {
    try {
        await scwin.cls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.btn_Cls_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ProcExcel_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리] 엑셀저장 버튼 클릭 — 선택한 탭의 두 그리드를 각각 내려받는다. (원본 doLogSave + fn_ExcelDown, doLogSave 삭제 — §6.8)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ProcExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.btn_ProcExcel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_SearchExcel_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리내역] 엑셀저장 버튼 클릭 — 선택한 탭의 두 그리드를 각각 내려받는다. (원본 doLogSave + fn_ExcelDown, doLogSave 삭제 — §6.8)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_SearchExcel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08200.btn_SearchExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 — 상장일(다음 영업일)·마감정보를 먼저 읽고(원본 동기 조회), 선택한 탭의 목록을 조회한다. (원본 fn_list_sync — §5)
 *  [ETN마감처리] 신규상장 목록(상장일 기준) → 첫 행 상환주기 → 버튼 상태
 *  [ETN마감처리내역] 신규상장 마감처리내역(마감일 기준) → 상환주기 마감처리내역 전체
 * @returns
 * @hidden N
 */
scwin.listSync = async function () {
    const taskDd = dma_search.get("taskDd");

    // 1) 상장일 — 원본 dts_Get_ListDD(동기) : 다음 영업일
    if (!await scwin.searchNextBzDay(taskDd)) return;

    // 2) 마감정보 — 원본 dts_Item(동기) : 담당자·팀장·전송시각
    if (!await scwin.searchCloseInfo(taskDd)) return;

    // 3) 선택한 탭의 목록
    if (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_SEARCH) {
        await scwin.searchHist(taskDd);
    } else {
        await scwin.searchList();
    }
};

/**
 * @method
 * @name scwin.searchNextBzDay
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장일(마감일의 다음 영업일) 조회 → 상장일 입력란(dma_nextBzDay.listDd). (원본 dts_Get_ListDD getElwListingListDd — §5.1)
 * @param {String} taskDd 마감일 (yyyyMMdd)
 * @returns {Promise<Boolean>} 다음 단계를 진행할지 (중복 실행으로 건너뛰면 false)
 * @hidden N
 */
scwin.searchNextBzDay = async function (taskDd) {
    dma_nextBzDay.setEmptyValue();

    const sbmOptions = {
        id : "sbm_searchNextBzDay",
        method : "get",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/next-bz-day",
        target : "dma_nextBzDay=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패해도 원본처럼 다음 조회를 이어 간다(원본 OnLoadError 는 안내만 — 오류 안내는 공통 핸들러).
    return true;
};

/**
 * @method
 * @name scwin.searchCloseInfo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 마감처리 정보(담당자·팀장·확인시각·전송시각) 조회 → dma_closeInfo. (원본 dts_Item searchLosslmtFinalLog — §5.2)
 * @param {String} taskDd 마감일 (yyyyMMdd)
 * @returns {Promise<Boolean>} 다음 단계를 진행할지 (중복 실행으로 건너뛰면 false)
 * @hidden N
 */
scwin.searchCloseInfo = async function (taskDd) {
    dma_closeInfo.setEmptyValue();

    const sbmOptions = {
        id : "sbm_searchCloseInfo",
        method : "get",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/close-info",
        target : "dma_closeInfo=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    return true;
};

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리] 신규상장 목록 조회(상장일 기준) → 건수 → 첫 행 상환주기 → 담당자 확인·팀장승인 버튼 상태.
 * (원본 dts_New_Proc listGeneral newlst.select.list.condition + OnLoadCompleted — §5.3)
 * @returns
 * @hidden N
 */
scwin.searchList = async function () {
    // 원본 Reset 은 다시 읽기 전에 비운다 — 실패해도 앞 조회 결과가 남지 않게 한다.
    dlt_list.removeAll();
    dlt_redemption.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_New_Proc_TotalCnt);
    $c.stf.fillGridHeaderTotalCnt(0, edt_Add_Proc_TotalCnt);

    const sbmOptions = {
        id : "sbm_searchList",
        method : "get",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/select-list",
        target : "dlt_list=body",
        gridview : "grd_New_Proc",
        isProcessMsg : false
    };

    // 원본 조회조건은 상장일({P}param01 = edt_LIST_DD) — 명세 요청 키는 taskDd 다.
    // TODO: select-list 의 taskDd 에 상장일을 넣는 것이 맞는지 확인 (§10 #3)
    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : dma_nextBzDay.get("listDd") });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        // 마감정보와 목록이 맞지 않는 상태로 처리하지 않도록 잠근다(§8 #9).
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    $c.stf.fillGridHeaderTotalCnt(dlt_list.getRowCount(), edt_New_Proc_TotalCnt);

    // 원본 OnLoadCompleted 는 NameValue(0, 'BZ_PROCS_NO')(1-base 에서 0행)로 상환주기를 다시 읽었다 — 첫 행으로 고친다(§8 #3).
    if (dlt_list.getRowCount() > 0) {
        await scwin.searchRedemption(dlt_list.getCellData(0, "bzProcsNo"));
    }

    scwin.applyButtonState();
};

/**
 * @method
 * @name scwin.searchRedemption
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리] 신규상장 한 건(업무처리번호)의 상환주기 목록 조회. 마지막 클릭이 이기도록 진행 중 조회는 중단한다.
 * (원본 fn_SearchRedmpt — dts_Add_Proc newlst.select.redmpt.condition — §5.4)
 * @param {String} bzProcsNo 업무처리번호(신청일련번호)
 * @returns
 * @hidden N
 */
scwin.searchRedemption = async function (bzProcsNo) {
    dlt_redemption.removeAll();     // 원본 dts_Add_Proc.ClearData()
    $c.stf.fillGridHeaderTotalCnt(0, edt_Add_Proc_TotalCnt);

    const sbmOptions = {
        id : "sbm_searchRedemption",
        method : "get",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/select-list-redemption",
        target : "dlt_redemption=body",
        gridview : "grd_Add_Proc",
        isProcessMsg : false
    };

    let result;
    try {
        result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : bzProcsNo ?? "" }, null, { onDuplicate : "abort" });
    } catch (err) {
        if (err?.aborted) return;   // 뒤 클릭이 이 조회를 중단함(onDuplicate "abort" 는 앞 요청을 reject 한다)
        throw err;
    }
    if (result?.skipped) return;
    if (!result?.responseJSON?.success) return;

    $c.stf.fillGridHeaderTotalCnt(dlt_redemption.getRowCount(), edt_Add_Proc_TotalCnt);
};

/**
 * @method
 * @name scwin.searchHist
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리내역] 신규상장 마감처리내역(마감일 기준) 조회 → 건수, 이어서 상환주기 마감처리내역 전체 조회.
 * (원본 dts_New_Search newlst.select.list.rv + dts_Add_Search newlst.select.redmpt.rv.all — §5.5, §5.6)
 * @param {String} taskDd 마감일 (yyyyMMdd)
 * @returns
 * @hidden N
 */
scwin.searchHist = async function (taskDd) {
    dlt_newlistingHist.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_New_Search_TotalCnt);

    const sbmOptions = {
        id : "sbm_searchHist",
        method : "get",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/select-list-hist",
        target : "dlt_newlistingHist=body",
        gridview : "grd_New_Search",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { taskDd : taskDd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (result.responseJSON?.success) {
        $c.stf.fillGridHeaderTotalCnt(dlt_newlistingHist.getRowCount(), edt_New_Search_TotalCnt);
    }

    // 원본은 신규상장 내역과 따로(비동기) 마감일 전체 상환주기 내역(rv.all)을 읽었다 — 종목코드 없이 조회.
    await scwin.searchRedemptionHist("");
};

/**
 * @method
 * @name scwin.searchRedemptionHist
 * @author Inswave
 * @date 2026. 10. 28
 * @description [ETN마감처리내역] 상환주기 마감처리내역 조회. 종목코드가 비면 마감일 전체(원본 rv.all), 있으면 그 종목(원본 rv.sel).
 * 마지막 클릭이 이기도록 진행 중 조회는 중단한다. (원본 dts_Add_Search / fn_SearchRedmptRv — §5.6)
 * @param {String} isuCd 종목코드 (빈 문자열이면 전체)
 * @returns
 * @hidden N
 */
scwin.searchRedemptionHist = async function (isuCd) {
    dlt_redemptionHist.removeAll();     // 원본 dts_Add_Search.ClearData()
    $c.stf.fillGridHeaderTotalCnt(0, edt_Add_Search_TotalCnt);

    const sbmOptions = {
        id : "sbm_searchRedemptionHist",
        method : "get",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/select-list-redemption-hist",
        target : "dlt_redemptionHist=body",
        gridview : "grd_Add_Search",
        isProcessMsg : false
    };

    // TODO: 명세는 isuCd 를 받지만 빈 값이면 마감일 전체인지(원본 rv.all) 확인 (§10 #4)
    const requestData = { taskDd : dma_search.get("taskDd"), isuCd : isuCd ?? "" };
    let result;
    try {
        result = await $c.sbm.executeDynamic(sbmOptions, requestData, null, { onDuplicate : "abort" });
    } catch (err) {
        if (err?.aborted) return;   // 뒤 클릭이 이 조회를 중단함(onDuplicate "abort" 는 앞 요청을 reject 한다)
        throw err;
    }
    if (result?.skipped) return;
    if (!result?.responseJSON?.success) return;

    $c.stf.fillGridHeaderTotalCnt(dlt_redemptionHist.getRowCount(), edt_Add_Search_TotalCnt);
};

/**
 * @method
 * @name scwin.postClose
 * @author Inswave
 * @date 2026. 10. 28
 * @description 마감 처리 전송(담당자 확인·팀장승인·재마감처리 공통). 성공하면 완료 안내 후 다시 조회하고, 실패하면 실패 안내.
 * 서브미션 옵션은 부르는 쪽이 전체 경로 리터럴 action 으로 만든다(전환 규칙 38). (원본 trs_revw / trs_Cls Post + OnSuccess·OnFail — §5.7~§5.9)
 * @param {Object} sbmOptions executeDynamic 옵션 (id·method·action·mediatype)
 * @param {Object} requestData 요청 본문
 * @returns
 * @hidden N
 */
scwin.postClose = async function (sbmOptions, requestData) {
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀 (원본 연속 클릭 — §8 #8)

    // TODO: 명세 응답이 비어 있어 성공은 success 로만 판정한다 — 업무 결과 코드가 있는지 확인 (§10 #6)
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    await scwin.listSync();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.applyTabMode
 * @author Inswave
 * @date 2026. 10. 28
 * @description 탭에 맞춰 마감일 입력 상태를 바꾼다. [ETN마감처리]는 마감일을 오늘로 고정(읽기전용), [ETN마감처리내역]은 입력 가능.
 * (원본 MaxTab_01 OnSelChanged 의 ReadOnly·img_TASK_DD.disabled·Text = 오늘 — §6.1)
 * @param {Number} index 탭 순번 (scwin.TAB_PROC | scwin.TAB_SEARCH)
 * @returns
 * @hidden N
 */
scwin.applyTabMode = function (index) {
    if (index === scwin.TAB_PROC) {
        dma_search.set("taskDd", scwin.todayDd);
        edt_TASK_DD.setReadOnly(true);
    } else {
        edt_TASK_DD.setReadOnly(false);
    }
};

/**
 * @method
 * @name scwin.checkProcDt
 * @author Inswave
 * @date 2026. 10. 28
 * @description 마감 처리 전 확인 — 마감일이 오늘인지, 발행시장참가자번호가 빈 신규상장 종목이 없는지. (원본 fn_checkProcDt — §6.2)
 * @param {String} jobNm 처리명 (안내 문구용)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.checkProcDt = async function (jobNm) {
    if (dma_search.get("taskDd") !== scwin.todayDd) {
        await $c.win.alert("[마감일]이 현재일경우만 '" + jobNm + "'를 할수 있습니다.");
        return false;
    }

    const rowCount = dlt_list.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        if ($c.util.isEmpty(dlt_list.getCellData(i, "isuMktpartcNo"))) {
            await $c.win.alert("발행회사명에 대한 시장참가자번호가 없는 종목이 있습니다. 시스템관리자에게 문의바랍니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name scwin.recls
 * @author Inswave
 * @date 2026. 10. 28
 * @description 재마감처리 — 이전 마감처리 기록을 지운다(다시 마감처리해야 함). (원본 fn_recls + fn_trSetHeader — §6.3, §5.9)
 * @returns
 * @hidden N
 */
scwin.recls = async function () {
    scwin.procJob = "재마감처리";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    const msg = "재마감처리를 선택 하셨습니다.\n재마감처리는 이전마감처리기록을 삭제하므로\n재마감처리후 다시 마감처리를 하셔야 됩니다.\n\n재마감처리를 하시겠습니까?";
    if (!await $c.win.confirm(msg)) return;

    // TODO: 명세 요청은 completeYn 하나 — 값의 의미 확인. 원본은 빈 LOSSLMT_ETN_FINAL_LOG_EMP 1행을 보냈다 (§10 #5)
    const sbmOptions = {
        id : "sbm_reClose",
        method : "post",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/reClose",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions, { completeYn : "" });
};

/**
 * @method
 * @name scwin.revw
 * @author Inswave
 * @date 2026. 10. 28
 * @description 담당자 확인. (원본 fn_revw + fn_trs_revw — §6.4, §5.7)
 * @returns
 * @hidden N
 */
scwin.revw = async function () {
    scwin.procJob = "담당자 확인";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    if (!await $c.win.confirm("담당자 확인 하시겠습니까?")) return;

    // TODO: 원본은 CHRG_EMP_NO(세션 사번)를 보냈으나 명세 요청은 completeYn 하나 — 서버 세션 처리인지 확인 (§10 #5)
    const sbmOptions = {
        id : "sbm_revwFinal",
        method : "post",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/revwFinal",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions, { completeYn : "" });
};

/**
 * @method
 * @name scwin.cls
 * @author Inswave
 * @date 2026. 10. 28
 * @description 팀장승인(마감처리). 담당자 확인 뒤에만 할 수 있다. 원본은 마감일 확인(fn_checkProcDt)을 주석 처리해 두었다. (원본 fn_cls + fn_trs — §6.5, §5.8)
 * @returns
 * @hidden N
 */
scwin.cls = async function () {
    if ($c.util.isEmpty(dma_closeInfo.get("approvTm"))) {
        await $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return;
    }

    scwin.procJob = "마감처리";
    // 원본 주석 처리 — if (! fn_checkProcDt(procJob)) return; (§8 #4, 그대로 유지)

    const listDd = dma_nextBzDay.get("listDd");
    if ($c.util.isEmpty(listDd)) {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }

    if (!await $c.win.confirm("마감처리 하시겠습니까?")) return;

    // TODO: 원본은 CHRG_EMP_NO(세션 사번)도 보냈으나 명세 요청은 listDd 하나 (§10 #5)
    const sbmOptions = {
        id : "sbm_apprvFinal",
        method : "post",
        action : "/api/listing/lstproc/etn/close-procs-newlisting/apprvFinal",
        mediatype : "application/json",
        isProcessMsg : false
    };
    await scwin.postClose(sbmOptions, { listDd : listDd });
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 28
 * @description 담당자 확인·팀장승인 버튼 활성. (원본 buttonSetDis — §6.6)
 *  팀장 확인(마감) 완료 → 둘 다 잠금 / 담당자 확인 전 → [담당자 확인]만 / 담당자 확인 후 → 팀장은 [팀장승인]만, 담당자는 둘 다 잠금.
 *  재마감처리 버튼도 다시 정한다.
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    const isClosed = !$c.util.isEmpty(dma_closeInfo.get("bzClsTm"));
    const isReviewed = !$c.util.isEmpty(dma_closeInfo.get("approvEmpNm"));
    const isChrg = (scwin.jobTitl === scwin.JOBTITL_CHRG);

    const enable = [];
    if (!isClosed) {
        if (!isReviewed) {
            enable.push("revw");
        } else if (!isChrg) {
            enable.push("cls");
        }
    }
    $c.util.setButtonState("grpBtnBox", { enable : enable }, scwin.BTN_MAP);

    scwin.applyReclsButton();
};

/**
 * @method
 * @name scwin.applyReclsButton
 * @author Inswave
 * @date 2026. 10. 28
 * @description 재마감처리 버튼 — 시스템관리자(ZSYS)만 보이고 활성, 그 밖에는 숨김. (원본 gform onload·buttonSetDis 의 showObj(btn_Recls) — §6.7)
 * @returns
 * @hidden N
 */
scwin.applyReclsButton = function () {
    if (scwin.depCd === scwin.DEP_CD_SYS) {
        btn_Recls.setDisabled(false);
        btn_Recls.show("");
    } else {
        btn_Recls.hide();
    }
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 28
 * @description 선택한 탭의 신규상장·상환주기 그리드를 파일 두 개로 내려받는다(원본도 GridToExcel 두 번). 0건 안내는 공통 함수가 한다.
 * 파일명은 {menuId}_{원본 이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42). (원본 fn_ExcelDown — §6.8)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    const prefix = $c.win.getProgramId() + "_";
    const suffix = "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx";

    if (Number(MaxTab_01.getSelectedTabIndex()) === scwin.TAB_SEARCH) {
        $c.data.downloadGridViewExcel(grd_New_Search, { fileName : prefix + "손실제한ETN 신규상장 송신목록" + suffix });
        // 원본 파일명 그대로(상환주기 그리드인데 "추가상장" — §8 #10)
        $c.data.downloadGridViewExcel(grd_Add_Search, { fileName : prefix + "손실제한ETN 추가상장 송신목록" + suffix });
    } else {
        $c.data.downloadGridViewExcel(grd_New_Proc, { fileName : prefix + "손실제한ETN 신규상장 마감처리목록" + suffix });
        $c.data.downloadGridViewExcel(grd_Add_Proc, { fileName : prefix + "손실제한ETN 상환주기 마감처리목록" + suffix });
    }
};
